package dev.raf.radar;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.function.LongSupplier;import org.json.*;
/** Only structured, allowlisted data. Throwable messages and user input never enter the journal. */
final class DiagnosticJournal {
 static final long HOUR=3600000L,REPORT_GAP=900000L;final File root;final LongSupplier clock;JSONArray events=new JSONArray();long lastReport;boolean dirty;
 DiagnosticJournal(File root,LongSupplier clock){this.root=root;this.clock=clock;root.mkdirs();try{events=new JSONArray(read(new File(root,"journal.json")));}catch(Exception ignored){}try{JSONObject state=new JSONObject(read(new File(root,"state.json")));lastReport=state.optLong("lastReport",0);dirty=state.optBoolean("dirty",false);}catch(Exception ignored){}prune();}
 static String word(String s){return s!=null&&s.matches("[a-zA-Z0-9_.$:-]{1,80}")?s:"unknown";}
 synchronized void event(String area,String event,String level,Throwable error,int http,long duration,long pause,String target){
  try{JSONObject e=new JSONObject().put("at",clock.getAsLong()).put("area",word(area)).put("event",word(event)).put("level",level);if(http>=100&&http<=599)e.put("http",http);if(duration>=0)e.put("durationMs",Math.min(3600000,duration));if(pause>=0)e.put("pauseSeconds",Math.min(86400,pause));if(target!=null)e.put("target",target.equals("own")?"own":target.equals("saved")?"saved":"none");
   if(error!=null){e.put("error",word(error.getClass().getSimpleName()));JSONArray frames=new JSONArray();Throwable cause=error;for(int n=0;n<3&&cause!=null;n++,cause=cause.getCause())for(StackTraceElement f:cause.getStackTrace())if(f.getClassName().startsWith("dev.raf.radar.")&&frames.length()<8)frames.put(f.getClassName()+"."+f.getMethodName()+":"+f.getLineNumber());e.put("frames",frames);}
   events.put(e);if(!"info".equals(level))dirty=true;prune();write(new File(root,"journal.json"),events.toString());state();
  }catch(Exception ignored){}
 }
 synchronized void prune(){long cutoff=clock.getAsLong()-HOUR;JSONArray kept=new JSONArray();for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e!=null&&e.optLong("at",0)>=cutoff&&e.optLong("at",0)<=clock.getAsLong()+5000)kept.put(e);}events=kept;while(events.length()>1200||events.toString().length()>250000){JSONArray tail=new JSONArray();for(int i=1;i<events.length();i++)tail.put(events.opt(i));events=tail;}File[] queued=root.listFiles((d,n)->n.startsWith("report-")&&n.endsWith(".json"));if(queued!=null){Arrays.sort(queued,Comparator.comparing(File::getName));for(int i=0;i<queued.length;i++)if(i<queued.length-8||clock.getAsLong()-queued[i].lastModified()>7L*86400000)queued[i].delete();}}
 synchronized File report(String trigger,JSONObject device,JSONObject snapshot,boolean force){prune();if(!dirty||(!force&&lastReport>0&&clock.getAsLong()-lastReport<REPORT_GAP&&clock.getAsLong()>=lastReport))return null;try{JSONObject report=new JSONObject().put("reportId",UUID.randomUUID().toString()).put("createdAt",clock.getAsLong()).put("trigger",word(trigger)).put("device",device).put("snapshot",snapshot).put("events",new JSONArray(events.toString()));File file=new File(root,"report-"+clock.getAsLong()+"-"+report.getString("reportId")+".json");write(file,report.toString());lastReport=clock.getAsLong();dirty=false;state();prune();return file;}catch(Exception e){return null;}}
 synchronized File pending(){prune();File[] files=root.listFiles((d,n)->n.startsWith("report-")&&n.endsWith(".json"));if(files==null||files.length==0)return null;Arrays.sort(files,Comparator.comparing(File::getName));return files[0];}
 synchronized void acknowledged(File f){f.delete();}
 synchronized void maintain(){prune();try{write(new File(root,"journal.json"),events.toString());}catch(Exception ignored){}}
 void state()throws IOException{try{write(new File(root,"state.json"),new JSONObject().put("lastReport",lastReport).put("dirty",dirty).toString());}catch(JSONException e){throw new IOException(e);}}
 static String read(File file)throws IOException{return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
 static void write(File file,String value)throws IOException{File temp=new File(file.getPath()+".tmp");try(FileOutputStream stream=new FileOutputStream(temp)){stream.write(value.getBytes(StandardCharsets.UTF_8));stream.getFD().sync();}try{Files.move(temp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
}
